class Developer { constructor(name) { this.name = name; this.type = "Dev"; } }
class Designer { constructor(name) { this.name = name; this.type = "Designer"; } }

// The Factory
class EmployeeFactory {
  create(name, type) {
    switch(type) {
      case "dev": return new Developer(name);
      case "designer": return new Designer(name);
      default: throw new Error("Unknown Employee Type");
    }
  }
}

const factory = new EmployeeFactory();
const employees = [];

// Clean, simple creation logic without needing to import specific classes everywhere
employees.push(factory.create("Alice", "dev"));
employees.push(factory.create("Bob", "designer"));
